const $ = id => document.getElementById(id);
const elements = {
    name: $('char-name'),
    gender: $('char-gender'), // <-- 新增
    class: $('char-class'),
    background: $('char-background'),
    species: $('char-species'),
    customBgEditor: $('custom-bg-editor'), // 新增
    customBgDesc: $('custom-bg-desc'),     // 新增
    customBgFeat: $('custom-bg-feat'),     // 新增
    customBgSkillsGrid: $('custom-bg-skills-grid'), // 新增
    lineageSelector: $('lineage-selector'),
    infoBoxes: $('info-boxes'),
    bgBonusSelector: $('bg-bonus-selector'),
    pointsRemaining: $('points-remaining'),
    attributesGrid: $('attributes-grid'),
    skillsTitle: $('skills-title'),
    skillsGrid: $('skills-grid'),
    humanFeatSection: $('human-feat-section'),

   humanFeatSelector: $('human-feat-selector'),
    validationMessages: $('validation-messages'),
    summaryBox: $('summary-box'),
    resetBtn: $('attr-reset'),
    recommendBtn: $('attr-recommend'),
    saveBtn: $('save-character')
};
// ========== 初始化 ==========
function init() {
    populateSelects();
    setupEventListeners();
    render();
}

function populateSelects() {
    elements.class.innerHTML = Object.keys(CLASSES).map(c => `<option value="${c}">${c}</option>`).join('');
    elements.background.innerHTML = Object.keys(BACKGROUNDS).map(b => `<option value="${b}">${b}</option>`).join('');
    elements.species.innerHTML = Object.keys(SPECIES).map(s => `<option value="${s}">${s}</option>`).join('');
    // 新增：填充自定义专长下拉框
    elements.customBgFeat.innerHTML = Object.keys(ORIGIN_FEATS).map(f => `<option value="${f}" ${state.customBg.feat === f ? 'selected' : ''}>${ORIGIN_FEATS[f].name}</option>`).join('');
}

// ========== 渲染函数 ==========

// 新增：辅助函数，用于获取动态背景（处理自定义）
function getDynamicBackground() {
    if (state.background === '自定义') {
        const featInfo = ORIGIN_FEATS[state.customBg.feat];
 return {
            ...BACKGROUNDS['自定义'], // 获取基础 gold, name 等
            desc: state.customBg.desc,
            feat: state.customBg.feat,
            skills: state.customBg.skills,
            featDesc: featInfo ?
 featInfo.name : '未选择',
            abilities: ATTRIBUTES // *关键：覆盖为所有属性
        };
    }
    return BACKGROUNDS[state.background];
}

function render() {
    elements.gender.value = state.gender; // <-- 新增
    renderLineageSelector();
    renderCustomBgEditor(); // 新增
    renderInfoBoxes();
    renderBgBonusSelector();
    renderAttributes();
    renderSkills();
    renderHumanFeat();
    renderValidation();
    renderSummary();
}

// 新增：渲染自定义背景编辑器
function renderCustomBgEditor() {
    if (state.background !== '自定义') {
        elements.customBgEditor.style.display = 'none';
 return;
    }
    elements.customBgEditor.style.display = 'block';
    elements.customBgDesc.value = state.customBg.desc;
    elements.customBgFeat.value = state.customBg.feat;
    // 渲染自定义技能网格
    const classSkills = new Set(CLASSES[state.class].skills_choice);
    elements.customBgSkillsGrid.innerHTML = SKILLS_LIST.map(skill => {
        const isSelected = state.customBg.skills.includes(skill);
        // 如果职业技能已选中，则禁止在背景中重复选择（虽然2024规则允许，但UI上简化）
        const isClassSkill = state.skills.includes(skill);
        const isDisabled = isClassSkill || (!isSelected && state.customBg.skills.length >= 2);

        let className = 'skill-pill';
        if (isSelected) className += ' proficient'; // 借用 'proficient' 样式
        if (isClassSkill) className += 
 ' background'; // 借用 'background' 样式
        if (isDisabled) className += ' disabled';

        return `<div class="${className}" data-skill="${skill}" data-disabled="${isDisabled}">${skill}</div>`;
    }).join('');
}

function renderLineageSelector() {
    const species = SPECIES[state.species];
 if (!species.hasLineage) {
        elements.lineageSelector.innerHTML = '';
        state.lineage = null;
        return;
    }

    const lineages = Object.keys(species.lineages);
 if (!state.lineage || !lineages.includes(state.lineage)) {
        state.lineage = lineages[0];
    }

    elements.lineageSelector.innerHTML = `
        <div class="field" style="margin-top: 16px;">
            <label for="lineage-select">血统/遗产</label>
            <select id="lineage-select">
                ${lineages.map(l => `<option value="${l}" ${state.lineage === l ? 'selected' : ''}>${l}</option>`).join('')}
            </select>
        </div>
    `;
 $('lineage-select').addEventListener('change', e => {
        state.lineage = e.target.value;
        render();
    });
}

function renderInfoBoxes() {
    const species = SPECIES[state.species];
    const bg = getDynamicBackground();
 // 修改
    const cls = CLASSES[state.class];
    let speciesInfo = `<h3>物种: ${state.species} (${species.name})</h3><p>${species.desc}</p>`;
    speciesInfo += `<p><b>特性:</b> ${species.traits.map(t => t.name).join(', ')}</p>`;
    if (species.hasLineage && state.lineage) {
        const lineage = species.lineages[state.lineage];
        speciesInfo += `<p><b>${state.lineage}血统:</b> ${lineage.desc}</p>`;
        if (lineage.traits) {
            speciesInfo += `<p><b>血统特性:</b> ${lineage.traits.map(t => t.name).join(', ')}</p>`;
        }
    }

    elements.infoBoxes.innerHTML = `
        <div class="info-box">${speciesInfo}</div>
        <div class="info-box">
            <h3>职业: ${state.class} (${cls.name})</h3>
            <p>${cls.desc}</p>
            <p><b>生命骰:</b> d${cls.hit_die} |
 <b>豁免熟练:</b> ${cls.saves.join(', ')}</p>
            <p><b>护甲与武器熟练:</b> ${cls.proficiencies.join(', ')}</p>
        </div>
        <div class="info-box">
            <h3>背景: ${state.background} ${state.background === '自定义' ?
 '' : `(${bg.name})`}</h3>
            <p>${bg.desc}</p>
            <p><b>技能熟练:</b> ${bg.skills.length > 0 ?
 bg.skills.join(', ') : '未选择'} |
            <b>起源专长:</b> ${bg.featDesc}</p>
        </div>
    `;
}

function renderBgBonusSelector() {
    const bg = getDynamicBackground(); // 修改
    const abilities = bg.abilities;
 // 如果是自定义，这里会是 ATTRIBUTES
    elements.bgBonusSelector.innerHTML = `
        <div style="margin-top: 16px; padding: 16px; background: var(--bg-alt); border-radius: 8px;">
            <div style="margin-bottom: 12px;">
                <label><input type="radio" name="bonus-mode" value="2+1" ${state.bgBonuses.mode === '2+1' ?
 'checked' : ''}> 
                选项A: +2/+1 分配</label>
            </div>
            <div style="display: ${state.bgBonuses.mode === '2+1' ? 'grid' : 'none'}; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 16px;"
 id="mode-2-1">
                <div class="field">
                    <label>+2 属性</label>
                    <select id="bonus-attr1">
                        ${abilities.map(a => `<option value="${a}" ${state.bgBonuses.attr1 === a ? 'selected' : ''} ${state.bgBonuses.attr2 === a ? 'disabled' : 

''}>${a}</option>`).join('')}

             </select>
                </div>
                <div class="field">
                    <label>+1 属性</label>
                    <select id="bonus-attr2">




            ${abilities.map(a => `<option value="${a}" ${state.bgBonuses.attr2 === a ? 'selected' : ''} ${state.bgBonuses.attr1 === a ? 'disabled' : ''}>${a}</option>`).join('')}
                    </select>
                </div>
            </div>


     <div style="margin-bottom: 12px;">


<label><input type="radio" name="bonus-mode" value="1+1+1" ${state.bgBonuses.mode === '1+1+1' ?
 'checked' : ''}> 
                选项B: +1/+1/+1 分配</label>
            </div>
            <div style="display: ${state.bgBonuses.mode === '1+1+1' ? 'block' : 'none'};"
 id="mode-1-1-1">
                <p style="margin: 8px 0; opacity: 0.8;">三个属性各 +1: ${abilities.join(', ')}</p>
            </div>
        </div>
    `;
 document.querySelectorAll('input[name="bonus-mode"]').forEach(radio => {
        radio.addEventListener('change', e => {
            state.bgBonuses.mode = e.target.value;
            if (state.bgBonuses.mode === '1+1+1') {
                state.bgBonuses.attr3 = abilities.find(a => a !== state.bgBonuses.attr1 && a !== state.bgBonuses.attr2);
            } else {
                state.bgBonuses.attr3 

= null;
            }
            render();
        });
    });
 if (state.bgBonuses.mode === '2+1') {
        $('bonus-attr1')?.addEventListener('change', e => {
            state.bgBonuses.attr1 = e.target.value;
            render();
        });
 $('bonus-attr2')?.addEventListener('change', e => {
            state.bgBonuses.attr2 = e.target.value;
            render();
        });
    }
}

function renderAttributes() {
    const pointCost = { 8:0, 9:1, 10:2, 11:3, 12:4, 13:5, 14:7, 15:9 };
 const usedPoints = ATTRIBUTES.reduce((acc, attr) => acc + pointCost[state.attributes[attr]], 0);
    const remainingPoints = 27 - usedPoints;
    elements.pointsRemaining.textContent = remainingPoints;
 const bg = getDynamicBackground(); // 修改

    elements.attributesGrid.innerHTML = ATTRIBUTES.map(attr => {
        const baseValue = state.attributes[attr];
        let bonus = 0;
        let bonusText = '';

        if (state.bgBonuses.mode === '2+1') {
            if (attr === state.bgBonuses.attr1) { bonus = 2; bonusText = '背景+2'; }

     else if (attr === 
state.bgBonuses.attr2) { bonus = 1; bonusText = '背景+1'; }
        } else {
            if (bg.abilities.includes(attr)) { bonus = 1; bonusText = '背景+1'; }
        }

        const finalValue = baseValue + bonus;
        const mod = Math.floor((finalValue - 10) / 2);


 const nextCost = (baseValue < 13) ? 1 : 
2;
        const canIncrease = baseValue < 15 && remainingPoints >= nextCost;
        const canDecrease = baseValue > 8;

        return `
            <div class="attr-row">
                <span class="attr-name">${attr}</span>


  <span class="attr-val">${finalValue}</span>

                <span class="attr-mod">${mod >= 0 ?
 '+' : ''}${mod}</span>
                <span class="attr-bonus">${bonusText}</span>
                <div class="attr-controls">
                    <button data-attr="${attr}" data-op="dec" ${!canDecrease ?
 'disabled' : ''}>-</button>
                    <button data-attr="${attr}" data-op="inc" ${!canIncrease ?
 'disabled' : ''}>+</button>
                </div>
            </div>
        `;
 }).join('');
}

function renderSkills() {
    const cls = CLASSES[state.class];
    const bg = getDynamicBackground();
 // 修改
    const bgSkills = new Set(bg.skills);
 // 如果自定义，则来自 state.customBg.skills
    const chosenSkills = state.skills.filter(s => !bgSkills.has(s));

    elements.skillsTitle.textContent = `5. 技能熟练 (从职业列表中选择 ${cls.skill_count} 项)`;
    elements.skillsGrid.innerHTML = SKILLS_LIST.map(skill => {
        const isBgSkill = bgSkills.has(skill);
        const isProficient = state.skills.includes(skill) || isBgSkill;
        const isChoice = cls.skills_choice.includes(skill);
        let className = 'skill-pill';
        let disabled = false;

        if (isBgSkill) { className += ' background'; }
        else if (isProficient) { className += ' proficient'; 

}
        // 职业技能选择已满，且当前技能不是已选中的职业技能
        if (!isChoice || (chosenSkills.length >= cls.skill_count && !state.skills.includes(skill))) {
            disabled = true;
            className += ' disabled';
        }

        // ========== BUG 修复 ==========
        // 背景技能总是禁用的（在职业选择器中）

 // 之前只设置了 disabled = true, 但没有添加 'disabled' 类, 导致视觉上没变灰
        if (isBgSkill) {
            disabled = true;
            if (!className.includes('disabled')) {
                className += ' disabled';
            }
        }
        // ========== 修复结束 ==========


        return `<div class="skill-pill ${className}" data-skill="${skill}" data-disabled="${disabled}">${skill}</div>`;
    }).join('');
}

function renderHumanFeat() {
    const isHuman = state.species === '人类';
    elements.humanFeatSection.style.display = isHuman ? 'block' : 'none';
 if (!isHuman) {
        state.humanFeat = null;
        return;
    }

    const bg = getDynamicBackground();
 // 修改
    const bgFeat = bg.feat;
    const availableFeats = Object.keys(ORIGIN_FEATS).filter(f => f !== bgFeat);
    elements.humanFeatSelector.innerHTML = availableFeats.map(feat => {
        const info = ORIGIN_FEATS[feat];
        const isSelected = state.humanFeat === feat;
        return `
            <div class="feat-option ${isSelected ? 'selected' : ''}" data-feat="${feat}">
                <h4>${info.name}</h4>
                <p>${info.desc}</p>



     </div>
        `;
    }).join('');
}

function renderValidation() {
    const errors = [];
    const cls = CLASSES[state.class];
    const bg = getDynamicBackground();
 // 修改
    const bgSkills = new Set(bg.skills);
    const chosenSkills = state.skills.filter(s => !bgSkills.has(s));
 // 检查技能选择
    if (chosenSkills.length !== cls.skill_count) {
        errors.push(`请从职业列表中选择 ${cls.skill_count} 个技能（当前已选 ${chosenSkills.length} 个）`);
    }

    // 新增：检查自定义背景技能
    if (state.background === '自定义' && state.customBg.skills.length !== 2) {
        errors.push('请为自定义背景选择 2 个技能熟练');
    }

    // 检查人类专长
    if (state.species === '人类' && !state.humanFeat) {
        errors.push('作为人类，你必须选择一个额外的起源专长');
    }

    // 检查属性点
    const pointCost = { 8:0, 9:1, 10:2, 11:3, 12:4, 13:5, 14:7, 15:9 };
 const usedPoints = ATTRIBUTES.reduce((acc, attr) => acc + pointCost[state.attributes[attr]], 0);
 if (usedPoints !== 27) {
        errors.push(`属性点数必须全部使用（剩余 ${27 - usedPoints} 点）`);
    }

    // 检查背景加值冲突
    if (state.bgBonuses.mode === '2+1' && state.bgBonuses.attr1 === state.bgBonuses.attr2) {
        errors.push('两个属性加值不能选择相同的属性');
    }

    elements.validationMessages.innerHTML = errors.length > 0
        ?
 `<div class="validation-error">${errors.map(e => `• ${e}`).join('<br>')}</div>`
        : '';

    elements.saveBtn.disabled = errors.length > 0;
}

function renderSummary() {
    const cls = CLASSES[state.class];
    const species = SPECIES[state.species];
    const bg = getDynamicBackground();
 // 修改
    // 计算最终属性
    const finalAttrs = {};
 ATTRIBUTES.forEach(attr => {
        let bonus = 0;
        if (state.bgBonuses.mode === '2+1') {
            if (attr === state.bgBonuses.attr1) bonus = 2;
            else if (attr === state.bgBonuses.attr2) bonus = 1;
        } else {
            if (bg.abilities.includes(attr)) bonus = 1;

        }


       finalAttrs[attr] = state.attributes[attr] + bonus;
    });
 const conMod = Math.floor((finalAttrs['体质'] - 10) / 2);
    const dexMod = Math.floor((finalAttrs['敏捷'] - 10) / 2);
 const hp = cls.hit_die + conMod;

    // 计算AC（考虑装备）
    let ac = 10 + dexMod;
 cls.equipment.forEach(item => {
        if (item.type === 'armor' && item.isEquipped) {
            if (item.armorType === 'shield') {
                ac += item.baseAc;
            } else if (item.armorType === 'light') {
                ac = item.baseAc + dexMod;


            } else if (item.armorType === 'medium') {
                ac = item.baseAc + Math.min(dexMod, 2);
            } else if (item.armorType === 'heavy') {
                ac = item.baseAc;
            }
        }

 });
    // 收集专长
    const feats = [bg.featDesc];
 if (state.humanFeat) {
        feats.push(ORIGIN_FEATS[state.humanFeat].name);
    }

    // 收集技能
    const allSkills = [...new Set([...bg.skills, ...state.skills])];
 let speciesText = state.species;
    if (state.lineage) speciesText += ` (${state.lineage})`;
 // --- 新增：收集法术 ---
    const classKnownSpells = cls.spells_known || { cantrips: [], level1: [] };
 const racialSpells = { cantrips: [], level1: [] };
    const speciesTraits = [...species.traits];
 if (species.hasLineage && state.lineage && species.lineages[state.lineage].traits) {
        speciesTraits.push(...species.lineages[state.lineage].traits);
    }

    const traitSpellMap = {
        '光明术': { cantrips: ['光明术'] },
        '卓尔魔法': { cantrips: ['舞光术'] },
        '魔法伎俩': { cantrips: ['魔法伎俩'] },
        '木精灵魔法': { cantrips: ['德鲁伊伎俩'] },
        '次级幻术': { cantrips: ['次级幻术'] },
        '动物交谈': { level1: ['动物交谈 '] },
        '工匠学识': { cantrips: ['修补术', '魔法伎俩'] }, //        
        '深渊魔法': { cantrips: ['毒气喷涌'] },
        '幽冥魔法': { cantrips: ['颤栗之触'] },
        '炼狱魔法': { cantrips: ['火焰箭'] }
    };
  speciesTraits.forEach(trait => {
        if (traitSpellMap[trait.name]) {
            const spells = traitSpellMap[trait.name];
            if (spells.cantrips) racialSpells.cantrips.push(...spells.cantrips);
            if (spells.level1) racialSpells.level1.push(...spells.level1);
        }
    });

    const allKnownSpells = {
        cantrips: [...new Set([...(classKnownSpells.cantrips || []), ...racialSpells.cantrips])],
        level1: [...new Set([...(classKnownSpells.level1 || []), ...racialSpells.level1])]
    };

    const finalSlots = {
        "1":{total: cls.spell_slots?.['1'] || 0, used:0},
        "2":{total:0,used:0}, "3":{total:0,used:0}, "4":{total:0,used:0}, 
        "5":{total:0,used:0}, "6":{total:0,used:0}, "7":{total:0,used:0}, 
        "8":{total:0,used:0}, "9":{total:0,used:0}
    };
let spellText = '';
if (allKnownSpells.cantrips.length > 0 || allKnownSpells.level1.length > 0) {
    spellText = '<strong>已知法术:</strong><br>';
    if (allKnownSpells.cantrips.length > 0) {
        spellText += `• 戏法: ${allKnownSpells.cantrips.join(', ')}<br>`;
    }
    if (allKnownSpells.level1.length > 0) {
        spellText += `• 1级法术: ${allKnownSpells.level1.join(', ')} (法术位: ${finalSlots['1'].total})<br>`;
    }
}
    // --- 结束：收集法术 ---

    // ========== 代码修改：在总览中加入性别 ==========
    elements.summaryBox.innerHTML = `
        <p>
            <strong>${state.name}</strong>，一位 ${state.gender} ${speciesText} ${state.class}，曾是一名 ${state.background}。<br>
            <strong>生命值:</strong> ${hp} |
 <strong>护甲等级:</strong> ${ac} | <strong>移速:</strong> ${species.speed}尺 | <strong>熟练加值:</strong> +2<br>
            <strong>属性:</strong> 
            力 ${finalAttrs['力量']}(${Math.floor((finalAttrs['力量']-10)/2)}), 
            敏 ${finalAttrs['敏捷']}(${dexMod}), 
            体 ${finalAttrs['体质']}(${conMod}), 
            智 ${finalAttrs['智力']}(${Math.floor((finalAttrs['智力']-10)/2)}), 
            感 ${finalAttrs['感知']}(${Math.floor((finalAttrs['感知']-10)/2)}), 


            魅 ${finalAttrs['魅力']}(${Math.floor((finalAttrs['魅力']-10)/2)})<br>
            <strong>豁免熟练:</strong> ${cls.saves.join(', ')}<br>
            <strong>技能熟练:</strong> ${allSkills.join(', ')}<br>
            <strong>起源专长:</strong> ${feats.join(', ')}<br>
            ${spellText}
            <strong>职业特性:</strong> ${cls.features.map(f => f.name).join(', ')}
        </p>
    `;
    // ========== 修改结束 ==========
}

// ========== 事件处理 ==========
function setupEventListeners() {
    elements.name.addEventListener('input', e => { state.name = e.target.value; render(); });
    elements.gender.addEventListener('change', e => { state.gender = e.target.value; render(); }); // <-- 新增
    elements.class.addEventListener('change', e => { state.class = e.target.value; state.skills = []; handleRecommendAttributes(); render(); });
    elements.background.addEventListener('change', e => { 
        state.background = e.target.value;
        const bg = getDynamicBackground(); // 修改
        state.bgBonuses.attr1 = bg.abilities[0];
        state.bgBonuses.attr2 = bg.abilities[1];
        state.skills = []; // 清除职业技能选择
        // 注意：不清除 state.customBg.skills
        render();
    });
    elements.species.addEventListener('change', e => { state.species = e.target.value; render(); });

    // 新增：自定义背景编辑器事件
    elements.customBgDesc.addEventListener('input', e => {
        state.customBg.desc = e.target.value || '一段独特的过往经历...';
        renderInfoBoxes(); // 仅更新信息框
        renderSummary();   // 仅更新总览
    });
    elements.customBgFeat.addEventListener('change', e => {
        state.customBg.feat = e.target.value;
        render(); // 需完全重绘 (影响人类专长/总览/信息框)
    });
    elements.customBgSkillsGrid.addEventListener('click', e => {
        const pill = e.target.closest('.skill-pill');
        if (!pill || pill.dataset.disabled === 'true') return;
        const skill = pill.dataset.skill;
        const index = state.customBg.skills.indexOf(skill);
        if (index > -1) {
            state.customBg.skills.splice(index, 1);
        } else if (state.customBg.skills.length < 2) {

  state.customBg.skills.push(skill);
        }
        render(); // 需完全重绘 (影响技能/总览/信息框/验证)
    });
    elements.attributesGrid.addEventListener('click', e => {
        const button = e.target.closest('button');
        if (!button) return;
        const attr = button.dataset.attr;
        const op = button.dataset.op;
        if (op === 'inc') state.attributes[attr]++;
        if (op === 'dec') state.attributes[attr]--;
        render();
    });
    elements.skillsGrid.addEventListener('click', e => {
