            }

            async function saveData() {
                if (!activeCharacterName) return;
                allCharacters[activeCharacterName] = characterData;

                try {
                    const payload = { stat_data: { allCharacters: [allCharacters, "Character sheet data object"], activeCharacterId: [activeCharacterName, "Active character name"] } };
                    await window.insertOrAssignVariables(payload, { type: 'chat' });
                    try { const msgId = (typeof window.getCurrentMessageId === 'function') ? window.getCurrentMessageId() : null; if (msgId) { await window.insertOrAssignVariables(payload, { type: 'message', message_id: msgId }); }
                    } catch (err) { console.error("Error writing stat_data to message scope:", err); }
