 char.proficiencies.expertises = char.proficiencies.expertises ?? [];
                char.proficiencies.weaponAndArmor = char.proficiencies.weaponAndArmor ?? [];

                char.inventory.weapons = (char.inventory.weapons || []).map(w => ({ ...w, details: w.details || '' }));
