                    try {
                        const chatVars = window.getVariables({ type: 'chat' });
                        const stat_data = chatVars.stat_data || {};
                        allCharacters = stat_data.allCharacters ? stat_data.allCharacters[0] : {};
                        activeCharacterName = stat_data.activeCharacterId ? stat_data.activeCharacterId[0] : null;
                    } catch (e) {
                        console.error("Error loading data from SillyTavern:", e);
                        allCharacters = {}; activeCharacterName = null;
                    }
                } else {
                     console.log("Tavern API not found. Using local default data.");
                     allCharacters = {}; activeCharacterName = null;
                }

                if (Object.keys(allCharacters).length === 0) {
                    console.log("No characters found. Creating a new default character.");
                    const newChar = JSON.parse(JSON.stringify(defaultCharacterData));
                    newChar.name = "新角色"; 
                    allCharacters[newChar.name] = newChar;
                    activeCharacterName = newChar.name;
