const PLACEHOLDER_NAMES = ["初始模板"];
// ========== DOM 元素 ==========
const $ = id => document.getElementById(id);
const elements = {
    name: $('char-name'),
    gender: $('char-gender'), // <-- 新增
    class: $('char-class'),
