                }

                if (Object.keys(allCharacters).length === 0) {
                    console.log("No characters found. Creating a new default character.");
                    const newChar = JSON.parse(JSON.stringify(defaultCharacterData));
                    newChar.name = "新角色"; 
                    allCharacters[newChar.name] = newChar;
                    activeCharacterName = newChar.name;
                } else {
                    if (!activeCharacterName || !allCharacters[activeCharacterName]) {
                        activeCharacterName = Object.keys(allCharacters)[0];
                    }
                }

                characterData = sanitizeCharacterData(allCharacters[activeCharacterName]);

                if (!characterData) {
                    console.error("Critical error: Active character data could not be loaded.");
                    return;
                }

                updateCharacterAC(false); 
                renderAll(); 
                renderCharacterSwitcher();
            }

            function waitForApi() {
                let attempts = 0; const maxAttempts = 30;
                const interval = setInterval(() => {
                    if (typeof window.getVariables === 'function' && typeof window.insertOrAssignVariables === 'function') {
                        clearInterval(interval); initializeApp();
                    } else { attempts++; if (attempts >= maxAttempts) { clearInterval(interval); console.log("Tavern API not found after 3 seconds."); initializeApp(); } }
                }, 100);
            }

            function showSaveNotification() {
                const notification = document.getElementById('save-notification');
                notification.style.opacity = '1';
                setTimeout(() => { notification.style.opacity = '0'; }, 1500);
            }

            function createNewCharacter() {
                let baseName = "新角色"; let newName = baseName; let counter = 2;
                while(allCharacters[newName]) { newName = `${baseName} ${counter}`; counter++; }
                const newChar = JSON.parse(JSON.stringify(defaultCharacterData));
                newChar.name = newName; newChar.portrait = `blank.png`;
                allCharacters[newName] = newChar;
                switchCharacter(newName);
            }

            function switchCharacter(name) {
                if (!allCharacters[name]) return;
                activeCharacterName = name;
                characterData = sanitizeCharacterData(allCharacters[name]);
                isEditing = false; isEditingSpellSlots = false;
                updateCharacterAC(false); 
                renderAll(); renderCharacterSwitcher(); saveData();
            }

            function deleteCharacter(name, event) {
                event.stopPropagation();
                if (Object.keys(allCharacters).length <= 1) { alert("不能删除最后一个角色！"); return; }
                if (confirm(`你确定要永久删除角色 "${name}" 吗？`)) {
                    delete allCharacters[name];
                    if (activeCharacterName === name) { const newActiveName = Object.keys(allCharacters)[0]; switchCharacter(newActiveName); } 
                    else { renderCharacterSwitcher(); saveData(); }
                }
            }

            const getModifier = (score) => Math.floor((parseInt(score, 10) - 10) / 2);
            const getModifierString = (score) => { const mod = getModifier(score); return mod >= 0 ? `+${mod}` : `${mod}`; };
/**
             * (新增) 辅助函数：检查角色是否拥有某个特性
             * @param {string} featureName - 要检查的特性名称 (模糊匹配, 不区分大小写)
             * @returns {boolean}
             */
            function hasFeature(featureName) {
                if (!characterData || !characterData.features) return false;
                const lowerCaseName = featureName.toLowerCase().trim();
                if (lowerCaseName === "") return false;

                const classFeatures = characterData.features.class || [];
                const raceFeatures = characterData.features.race || [];

                // 检查特性名称是否 *包含* 关键字 (例如, "专长: 警觉" 也能匹配 "警觉")
                const check = (feature) => feature.name && feature.name.toLowerCase().includes(lowerCaseName);

                return classFeatures.some(check) || raceFeatures.some(check);
            }

            /**
             * (新增) 辅助函数：计算先攻加值
             * @returns {number}
             */
            function calculateInitiative() {
                const dexMod = getModifier(characterData.stats.dex);
                let initiativeBonus = dexMod;

                // 1. 检查 "警觉" 专长 (2024版规则: +熟练加值)
                const hasAlert = hasFeature("警觉");
                if (hasAlert) {
                    initiativeBonus += characterData.proficiencyBonus;
                }

                // 2. 检查 诗人的 "万事通" (Jack of All Trades)
                // 规则: 任何未添加熟练的属性检定, 加上一半熟练 (向下取整)
                // "警觉" 已经添加了熟练, 所以 "万事通" 不会再叠加
                const isBard = (characterData.class || '').toLowerCase().includes('诗人');
                const hasJoAT = hasFeature("万事通");

                if (isBard && hasJoAT && !hasAlert) { // 必须没有警觉 (或其他加PB的特性)
                    initiativeBonus += Math.floor(characterData.proficiencyBonus / 2);
                }

                return initiativeBonus;
            }

           function calculateAC() {
                if (!characterData || !characterData.stats) return 10;

                const dexMod = getModifier(characterData.stats.dex);
                const equippedItems = (characterData.inventory.equipment || []).filter(item => item.isEquipped && item.type === 'armor');

                // 提前定义装备
                const baseArmor = equippedItems.find(item => ['light', 'medium', 'heavy'].includes(item.armorType));
                const unarmoredEffect = equippedItems.find(item => item.armorType === 'unarmoredEffect');
                const shield = equippedItems.find(item => item.armorType === 'shield');

                let baseAc = 10 + dexMod; // 默认AC计算 (10 + 敏捷)

                if (baseArmor) {
                    // --- 1. 穿着盔甲 ---
                    baseAc = baseArmor.baseAc;
                    if (baseArmor.armorType === 'light') baseAc += dexMod;
                    else if (baseArmor.armorType === 'medium') baseAc += Math.min(dexMod, 2);

                } else {
                    // --- 2. 未穿盔甲 ---
                    // "无甲" 来源可以有多个, 角色取最高值 (例如: 10+敏捷, 法师护甲, 野蛮人无甲, 武僧无甲)
                    let unarmoredOptions = [baseAc]; // 至少是 10 + 敏捷

                    if (unarmoredEffect) {
                        unarmoredOptions.push(unarmoredEffect.baseAc + dexMod); // 例如 "法师护甲 (效果)"
                    }

                    // 检查 "无甲防御" 特性
                    const hasUnarmoredDefense = hasFeature("无甲防御");
                    if (hasUnarmoredDefense) {
                        const isBarbarian = (characterData.class || '').toLowerCase().includes('野蛮人');
                        if (isBarbarian) {
                            // 野蛮人无甲: 10 + 敏捷 + 体质 (可以拿盾)
                            const conMod = getModifier(characterData.stats.con);
                            unarmoredOptions.push(10 + dexMod + conMod);
                        }

                        const isMonk = (characterData.class || '').toLowerCase().includes('武僧');
                        if (isMonk && !shield) { // 武僧无甲: *不能* 拿盾
                            const wisMod = getModifier(characterData.stats.wis);
                            unarmoredOptions.push(10 + dexMod + wisMod);
                        }
                    }

                    baseAc = Math.max(...unarmoredOptions); // 取所有无甲选项中最高的一个
                }

                // --- 3. 最终AC计算 ---
                let totalAC = baseAc;

                // 添加盾牌加值
                if (shield) {
                    totalAC += shield.baseAc;
                }

                // 添加 "防御" 战斗风格
                // (注意: hasFeature 是我们新增的辅助函数)
                if (hasFeature("战斗风格: 防御") && (baseArmor || shield)) { // 必须穿甲或拿盾
                    totalAC += 1; 
                }

                return totalAC;
            }

            function updateCharacterAC(shouldSave = true) {
                characterData.ac = calculateAC();
                if (shouldSave) saveData();
                const acDisplay = document.getElementById('ac-display');
                if(acDisplay) acDisplay.textContent = characterData.ac;
            }

            function longRest() {
                if (!confirm("确定要进行一次长休吗？")) return;
                characterData.currentHp = characterData.maxHp;
                characterData.currentHitDice = characterData.maxHitDice;
                characterData.deathSaves = { success: 0, failure: 0 };
                for (const level in characterData.spells.slots) { if(characterData.spells.slots[level]) characterData.spells.slots[level].used = 0; }
                (characterData.resources || []).forEach(r => r.current = r.max);
                saveData(); 
                renderAll();
            }

            function renderAll() {
                if (!characterData) return;
                renderHeader(); renderSidebar(); renderAttributesTab(); renderInventoryTab();
                renderFeaturesTab(); renderSpellsTab(); renderBioTab(); updateEditModeUI();
            }

            function getPortraitSrc(portraitRef) {
                const src = portraitRef || '';
                if (src.startsWith('http://') || src.startsWith('https://')) { return src; } 
                else if (src.trim() !== '') { return `/p/${src}`; } 
                else { return 'https://placehold.co/200x267/495057/adb5bd?text=无肖像'; }
            }

            function renderCharacterSwitcher() {
                const switcher = document.getElementById('character-switcher');
                switcher.innerHTML = '';
                Object.values(allCharacters).forEach(char => {
                    const btn = document.createElement('div');
                    btn.className = 'char-portrait-btn'; btn.title = char.name; btn.dataset.id = char.name;
                    if (char.name === activeCharacterName) btn.classList.add('active');
                    btn.innerHTML = `<img src="${getPortraitSrc(char.portrait)}" alt="${char.name}"><div class="delete-char-btn" title="删除角色"><i class="fa-solid fa-times"></i></div>`;
                    btn.addEventListener('click', () => switchCharacter(char.name));
                    btn.querySelector('.delete-char-btn').addEventListener('click', (e) => deleteCharacter(char.name, e));
                    switcher.appendChild(btn);
                });
                const addButton = document.createElement('div');
                addButton.id = 'add-char-btn'; addButton.className = 'add-char-btn'; addButton.title = '创建新角色';
