                     tempHpContainer.innerHTML = `<div class="flex items-center gap-2"><span>临时HP</span><input type="number" id="edit-temp-hp" class="edit-input text-center" value="${characterData.tempHp}"></div>`;
                     hitDiceContainer.innerHTML = `<div class="flex items-center gap-2"><input type="number" id="edit-current-hd" class="edit-input text-center" value="${characterData.currentHitDice}"><span>/</span><input type="number" id="edit-max-hd" class="edit-input text-center" value="${characterData.maxHitDice}"></div>`;
