            function renderAttributesTab() {
                const container = document.getElementById('attributes');
                let statsHtml = Object.entries(characterData.stats).map(([stat, score]) => isEditing ? `<div class="stat-card-lg"><div class="text-sm text-gray-300">${stat.toUpperCase()}</div><input type="number" class="edit-input text-center text-3xl font-bold my-1" data-stat="${stat}" value="${score}"><div class="text-md text-gray-400">${getModifierString(score)}</div></div>` : `<div class="stat-card-lg"><div class="text-sm text-gray-300">${stat.toUpperCase()}</div><div class="text-3xl font-bold">${getModifierString(score)}</div><div class="text-md text-gray-400">${score}</div></div>`).join('');

                function getSkillBonus(skillName) {
                    const stat = characterData.skillToStatMap[skillName];
                    const proficiencies = characterData.proficiencies || {};
                    const isProficient = (proficiencies.skills || []).includes(skillName);
                    const isExpert = (proficiencies.expertises || []).includes(skillName);
                    let proficiencyBonusToAdd = isExpert ? characterData.proficiencyBonus * 2 : (isProficient ? characterData.proficiencyBonus : 0);
                    return getModifier(characterData.stats[stat]) + proficiencyBonusToAdd;
                }

                let skillsHtml = characterData.allSkills.map(skillName => {
                    const stat = characterData.skillToStatMap[skillName];
                    const proficiencies = characterData.proficiencies || {};
                    const isProficient = (proficiencies.skills || []).includes(skillName);
                    const isExpert = (proficiencies.expertises || []).includes(skillName);
                    const totalBonus = getSkillBonus(skillName);

                    if (isEditing) {
                        let profSymbol = isExpert ? '★' : (isProficient ? '●' : '○');
                        return `<li class="flex justify-between items-center px-2 py-1 rounded"><span><span class="proficiency-toggle select-none cursor-pointer text-lg" style="display: inline-block; width: 1.2em; text-align: center;" data-skill-name="${skillName}" title="点击切换熟练度: 无 -> 熟练 -> 专精">${profSymbol}</span> ${skillName} (${stat.toUpperCase()})</span><span class="font-semibold text-lg">${totalBonus >= 0 ? `+${totalBonus}` : totalBonus}</span></li>`;
                    } else {
