                        return `<li class="flex justify-between items-center px-2 py-1 rounded"><span><span class="text-lg" style="display: inline-block; width: 1.2em; text-align: center;">${profSymbol}</span> ${skillName} (${stat.toUpperCase()})</span><span class="font-semibold text-lg">${totalBonus >= 0 ? `+${totalBonus}` : totalBonus}</span></li>`;
                    }
                }).join('');

                let savesHtml = Object.entries(characterData.stats).map(([stat, score]) => {
