                    return `<li class="flex justify-between items-center px-2 py-1 rounded"><span>${isEditing ? `<input type="checkbox" data-save-prof="${stat}" ${isProficient ? 'checked' : ''}>` : (isProficient ? '●' : '○')} ${stat.toUpperCase()}</span><span class="font-semibold text-lg">${totalBonus >= 0 ? `+${totalBonus}` : totalBonus}</span></li>`;
