                    equipHtml = equipment.map((e, i) => e.type === 'armor' ? `<div class="list-item-grid grid-cols-[auto,1fr,auto] gap-3"><button class="info-btn" data-action="show-details" data-type="equipment" data-index="${i}"><i class="fa-solid fa-circle-info"></i></button><span>${e.name}</span><button class="equip-toggle ${e.isEquipped ? 'equipped' : ''}" data-equip-index="${i}">${e.isEquipped ? '已装备' : '装备'}</button></div>` : `<div class="list-item-grid grid-cols-[auto,1fr,auto] gap-3"><button class="info-btn" data-action="show-details" data-type="equipment" data-index="${i}"><i class="fa-solid fa-circle-info"></i></button><span>${e.name}</span><span class="text-right font-semibold">${e.quantity || 1}</span></div>`).join('');
