  _.add('allCharacters.0.查理.currentHp', 8);       // 可选：同步回血
  _.add('allCharacters.0.查理.maxHitDice', 1);      // 生命骰+1
  _.add('allCharacters.0.查理.currentHitDice', 1);

  /* 2) 本级新特性（示例：选冠军 Champion，占位写法） */
_.assign('allCharacters.0.查理.features.class.5', {
    "name": "武技之路：冠军（占位）",
    "details": "【示例】卓越重击：你的武器攻击在掷出19或20时造成重击（按你的规则版本调整描述）。"
  });

